    std::vector<float> pending(spec_state_.draft_pending_logits().begin(),
                               spec_state_.draft_pending_logits().end());
    for (int i = 0; i < K; i++) {
      if (!ff_queue.empty()) {
        // forced token: no draft prediction, no distribution
        proposal.tokens[i] = ff_queue.front();
        ff_queue.pop_front();
        if (!greedy) {
