class TestBarrier {
 public:
  explicit TestBarrier(size_t participant_count)
      : remaining_{participant_count} {}

  void ArriveAndWait() {
    std::unique_lock lock{mutex_};
    if (--remaining_ == 0) {
      condition_.notify_all();
      return;
    }
    condition_.wait(lock, [this] { return remaining_ == 0; });
  }

 private:
  std::mutex mutex_;
  std::condition_variable condition_;
  size_t remaining_;
};

