    const auto& prefill_entry = context.plan->requests[1];
    EXPECT_EQ(prefill_entry.request_id, prefill.get());
    EXPECT_EQ(prefill_entry.unprocessed_token_count, 1u);
    for (const auto& binding : context.fixed_state_bindings) {
