    ASSERT_EQ(RunOne(*guidance_engine.engine).request, request);
  }
  ASSERT_TRUE(request->IsTurnComplete());
  request->BeginTurn(std::array<int32_t, 1>{5});
  ASSERT_EQ(RunOne(*guidance_engine.engine).request, request);
  EXPECT_EQ(request->DraftTokenValidationError(), nullptr);
}

