  request->BeginTurn(std::array<int32_t, 1>{5}, StopOptions({"STOP"}));
  EXPECT_EQ(request->FinishReason(), GenerationFinishReason::None);
  EXPECT_EQ(request->MatchedStopStringIndex(), -1);

